public class AnnotatedIdentityTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        try {
            StaffMember a = new StaffMember("B7", "ops", "Ada", 12);
            StaffMember b = new StaffMember("B7", "ops", "Bo", 99);
            StaffMember c = new StaffMember("B7", "sales", "Ada", 12);
            ShelfBook one = new ShelfBook("978-1", 3);
            ShelfBook two = new ShelfBook("978-1", 40);

            check("only the @Identity fields count", true, AnnotatedIdentity.sameIdentity(a, b));
            check("a differing @Identity field breaks it", false,
                    AnnotatedIdentity.sameIdentity(a, c));
            check("different classes are never the same identity", false,
                    AnnotatedIdentity.sameIdentity(a, one));
            check("null is never the same identity", false, AnnotatedIdentity.sameIdentity(a, null));
            check("the hash is built from the annotated values",
                    java.util.Objects.hash("B7", "ops"), AnnotatedIdentity.identityHash(a));
            check("equal identities hash alike", true,
                    AnnotatedIdentity.identityHash(a) == AnnotatedIdentity.identityHash(b));
            check("a single-field model works too", true,
                    AnnotatedIdentity.sameIdentity(one, two));
            check("identityHash(null)", 0, AnnotatedIdentity.identityHash(null));
        } catch (Throwable t) {
            System.out.println("FAIL  unexpected " + t.getClass().getSimpleName() + ": " + t.getMessage());
            failures++;
        }

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

