public class AnnotatedIdentity {

    public static boolean sameIdentity(Object a, Object b) {
        if (a == null || b == null) {
            return false;
        }
        if (a.getClass() != b.getClass()) {
            return false;
        }
        for (Field field : a.getClass().getDeclaredFields()) {
            if (!field.isAnnotationPresent(Identity.class)) {
                continue;
            }
            field.setAccessible(true);
            try {
                if (!Objects.equals(field.get(a), field.get(b))) {
                    return false;
                }
            } catch (IllegalAccessException e) {
                return false;
            }
        }
        return true;
    }

    public static int identityHash(Object o) {
        if (o == null) {
            return 0;
        }
        List<Object> values = new ArrayList<>();
        for (Field field : o.getClass().getDeclaredFields()) {
            if (!field.isAnnotationPresent(Identity.class)) {
                continue;
            }
            field.setAccessible(true);
            try {
                values.add(field.get(o));
            } catch (IllegalAccessException e) {
                values.add(null);
            }
        }
        return Objects.hash(values.toArray());
    }
}
